type CommandReturn<C extends CommandName> = CommandResults[C] extends null ? void : CommandResults[C];
export function invokeCommand<C extends CommandName>(command: C, ...[args]: {} extends CommandArguments[C] ? [args?: CommandArguments[C]] : [args: CommandArguments[C]]): Promise<CommandReturn<C>> {
  return tauriInvoke<CommandReturn<C>>(command, args);
}

